// The World 2 event leagues (20 Oct 2026, the owner): from level 100 a farmer's league is one of six village leagues, with goals in the
// village and coins ×10 to ×20. A farmer who first counted in an event below level 100 finishes it in the Valley Legends (the owner's
// answer to question 6). The live switch is supabase/world-two-leagues-a.sql (Part A) and -b.sql (Part B), generated by
// scripts/world-two-leagues-sql.mjs.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {EVENT_LEAGUES,eventLeagueFor,eventLeagueIn,eventLeagueCount,NO_EVENT_ACTIONS,worldTwoItem} from '../public/farm-state.js';
import {EVENT_GOAL_POOLS,EVENT_GOAL_TITLES,EVENT_GOAL_TITLES_BEFORE_ONE_CROP,EVENT_GOAL_GROUPS} from '../public/event-goals.js';
import {EVENT_GOALS} from '../public/live-events-ui.js';
import {eventStandings} from '../supabase/functions/farm-api/event-service.js';
import {worldTwoLeaguesSql,LEAGUE_CASE,OLD_MD5,NEW_MD5} from '../scripts/world-two-leagues-sql.mjs';
import {PICK_BODY,VALIDATE_BODY} from '../scripts/event-goals-sql.mjs';
const read=path=>readFileSync(new URL(`../${path}`,import.meta.url),'utf8');
const md5=text=>createHash('md5').update(text).digest('hex');
const A=read('supabase/world-two-leagues-a.sql'),B=read('supabase/world-two-leagues-b.sql');
const body=(sql,name)=>{const at=sql.indexOf(`create or replace function public.${name}(`);assert.ok(at>=0,name);const from=sql.indexOf('$function$',at)+10;return sql.slice(from,sql.indexOf('$function$',from));};
const header=(sql,name)=>{const at=sql.indexOf(`create or replace function public.${name}(`);return sql.slice(at,sql.indexOf('$function$',at));};
const WORLD_TWO_STAT=stat=>stat.startsWith('made_')&&worldTwoItem(stat.slice(5))||['village_batches','village_requests','lake_fish','boat_trips'].includes(stat);

test('league helpers: an event keeps the leagues it was made with, and a farmer who first counted below 100 stays a Valley Legend',()=>{
 assert.equal(eventLeagueFor({leagues:Array(6)},150).id,'legends');assert.equal(eventLeagueFor({leagues:null},150).id,'legends');assert.equal(eventLeagueFor(null,150).id,'legends');
 assert.equal(eventLeagueFor({leagues:Array(12)},150).id,'linen');
 assert.equal(eventLeagueFor({leagues:Array(12)},100,1).id,'legends');assert.equal(eventLeagueFor({leagues:Array(12)},100,2).id,'cobble');
 assert.equal(eventLeagueFor({leagues:Array(12)},100,null).id,'cobble');assert.equal(eventLeagueFor({leagues:Array(12)},80,1).id,'estate');
 assert.equal(eventLeagueFor({leagues:Array(12)},250,1).id,'legends');assert.equal(eventLeagueFor({leagues:Array(12)},10).id,'sprout');
 assert.equal(eventLeagueIn({leagues:Array(6)},9).id,'legends');assert.equal(eventLeagueIn({leagues:Array(12)},9).id,'silver');
 assert.equal(eventLeagueIn({leagues:Array(12)},-3).id,'sprout');assert.equal(eventLeagueIn({leagues:Array(12)},40).id,'village');assert.equal(eventLeagueIn({leagues:Array(20)},40).id,'harbour');   // the harbour's leagues (27 Oct 2026)
 assert.equal(eventLeagueCount({leagues:[]}),6);assert.equal(eventLeagueCount({}),6);assert.equal(eventLeagueCount({leagues:Array(12)}),12);
});

test('pools: five groups in every league, never empty; the farm draws farm goals, the village village goals, the farm as before',()=>{
 assert.equal(EVENT_GOAL_POOLS.length,17);   // 12, and the harbour's five (27 Oct 2026)
 for(const [i,pool] of EVENT_GOAL_POOLS.entries()){
  const l=EVENT_LEAGUES[i];assert.equal(pool.length,5,l.id);
  for(const [k,group] of pool.entries())assert.ok(group.length>0,`${l.id}: group ${k} has a goal (harvest_event_pick divides by its size)`);
  const HARBOUR_STAT=stat=>/^(ship_loads|ships_sent|harbour_batches|harbour_sold|harbour_upgrades|seal_pats|made_(rope|barrel|shipsbiscuits|sailcloth|provisions|anchor|fishingnet|anchorchain))$/.test(stat);   // the harbour's (27 Oct 2026)
  for(const {stat} of pool.flat())assert.ok(l.world===1?!WORLD_TWO_STAT(stat)&&!HARBOUR_STAT(stat):l.world===2?WORLD_TWO_STAT(stat)||stat==='upgrades':HARBOUR_STAT(stat),`${l.id} ${stat}`);   // the harbour's own upgrades (28 Oct 2026), never the farm's
 }
 assert.deepEqual(EVENT_GOAL_POOLS.slice(6,12).map(p=>p.map(g=>g.length).join('/')),['3/1/2/1/2','4/2/5/1/2','4/4/9/1/2','4/4/11/1/2','4/4/11/1/2','4/4/11/1/2']);
 assert.equal(EVENT_GOAL_GROUPS[1].length,5);assert.deepEqual(EVENT_GOAL_GROUPS[2],['Mine and forest','Fields and kitchens','Workshops','Market square','Around the village']);
 // The farm leagues' pools are byte-identical to what harvest_event_pick drew before (supabase/live-event-league-goals.sql as live).
 const farm=JSON.stringify(EVENT_GOAL_POOLS.slice(0,6).map(l=>l.map(g=>g.map(({stat,targets})=>({stat,targets,titles:EVENT_GOAL_TITLES_BEFORE_ONE_CROP[stat]}))))).replaceAll("'","''");
 assert.equal(md5(farm),'badc8ae11b1bba4dcaf6b69cc21f5f62','the six farm pools as live (md5 of the live pools constant, 20 Oct 2026)');
 // A few numbers from the spec (20 Oct 2026).
 const t=(i,stat)=>EVENT_GOAL_POOLS[i].flat().find(g=>g.stat===stat)?.targets;
 assert.deepEqual(t(6,'made_stone'),[12,20,32]);assert.deepEqual(t(7,'made_clay'),[24,40,64]);assert.deepEqual(t(8,'made_lavender'),[45,75,150]);
 assert.deepEqual(t(11,'village_batches'),[50,85,150]);assert.deepEqual(t(11,'village_requests'),[2,3,5]);assert.deepEqual(t(9,'lake_fish'),[5,10,15]);
 assert.equal(t(6,'made_ironbar'),undefined,'iron bars join from the Timber League (the Smithy opens at 102)');
 assert.equal(t(11,'made_heirloomflour'),undefined);assert.equal(t(11,'boat_trips'),undefined);assert.equal(t(11,'made_saffron'),undefined);
});

test('goals on screen: every village goal has a name, a picture and two titles of its own',()=>{
 const titles=Object.values(EVENT_GOAL_TITLES).flat().map(([title])=>title);
 assert.equal(new Set(titles).size,titles.length,'every title once');
 for(const {stat} of EVENT_GOAL_POOLS.slice(6).flat(2)){
  assert.ok(EVENT_GOALS[stat]?.label&&EVENT_GOALS[stat]?.art&&EVENT_GOALS[stat].art!=='quests',stat);
  assert.equal(EVENT_GOAL_TITLES[stat]?.length,2,stat);
 }
 assert.deepEqual(EVENT_GOALS.lake_fish,{label:'Catch lake fish',art:'villagelake'});
 for(const [label] of Object.values(EVENT_GOALS).map(g=>[g.label]))assert.doesNotMatch(label,/ · /);
});

test('the generated SQL is up to date',()=>{
 const {a,b}=worldTwoLeaguesSql();
 assert.equal(A,a,'run node scripts/world-two-leagues-sql.mjs');assert.equal(B,b,'run node scripts/world-two-leagues-sql.mjs');
});

test('Part A: the wider check and the two columns, nothing else',()=>{
 assert.match(A,/^begin;\nset local lock_timeout='5s';/m);assert.match(A,/\ncommit;\n$/);
 assert.match(A,/add constraint live_event_players_league_check check \(league is null or league between 0 and 11\);/);
 assert.match(A,/alter table public\.live_event_players add column if not exists world smallint check \(world in \(1,2\)\);/);
 assert.match(A,/alter table public\.player_stats add column if not exists village_events_finished integer not null default 0;\ngrant select \(village_events_finished\) on public\.player_stats to authenticated;/);
 assert.doesNotMatch(A,/create or replace function/);
});

test('Part B: the leagues, the coins, the counter, the world, the village goals, the headers and the checks',()=>{
 assert.match(B,/^begin;\nset local lock_timeout='5s';\ndo \$guard\$/m);assert.match(B,/end \$after\$;\ncommit;\n$/);
 assert.equal(LEAGUE_CASE,'case when coalesce(p_level,0)>=201 then 11 when p_level>=181 then 10 when p_level>=161 then 9 when p_level>=141 then 8 when p_level>=121 then 7 when p_level>=100 then 6 when p_level>=90 then 5 when p_level>=75 then 4 when p_level>=60 then 3 when p_level>=45 then 2 when p_level>=30 then 1 else 0 end');
 assert.ok(body(B,'harvest_event_league').includes(`select (${LEAGUE_CASE})::smallint`));
 assert.match(body(B,'harvest_event_league_for'),/case when p_world=1 then 5 else 11 end/);
 assert.match(body(B,'harvest_event_league_for'),/then jsonb_array_length\(p_leagues\) else 6 end\)-1/);
 const settle=body(B,'harvest_event_settle'),progress=body(B,'harvest_event_progress'),board=body(B,'harvest_event_board');
 assert.ok(settle.includes('*(array[1,2,3,4,5,8,10,12,14,16,18,20])[r.league+1]'));assert.doesNotMatch(settle,/case r\.league when 5/);
 assert.match(settle,/village_events_finished=\(select count\(\*\) from public\.live_event_players lp where lp\.player_id=s\.player_id and lp\.qualified and lp\.league>=6\)/);
 assert.match(settle,/set league=public\.harvest_event_league_for\(s\.level,e\.leagues,p\.world\)/);
 assert.match(progress,/lg:=public\.harvest_event_league_for\(lv,e\.leagues,p\.world\);\n  objs:=coalesce\(e\.leagues->lg->'objectives',e\.objectives\);/);
 assert.match(board,/coalesce\(lp\.league,public\.harvest_event_league_for\(s\.level,e\.leagues,lp\.world\)\)/);
 assert.match(board,/from public\.live_event_players lp join public\.live_events e on e\.id=lp\.event_id left join/);
 // The world: written once, with the first progress, never in the update.
 assert.match(progress,/p\.world:=case when public\.harvest_event_league\(lv\)>=6 then 2 else 1 end;end if;/);
 assert.match(progress,/insert into public\.live_event_players\(event_id,player_id,progress,actions,joined_at,last_at,baseline,world\)\n    values\([^\n]*,p\.baseline,p\.world\)/);
 const update=progress.slice(progress.indexOf('on conflict(event_id,player_id) do update set'));assert.doesNotMatch(update.slice(0,update.indexOf(';')),/world/);
 for(const clause of ["(stat='village_batches' and action in ('collect','collect_all'))","(stat='village_requests' and action='village_deliver')","(stat='lake_fish' and action='lake_fish')","(stat='boat_trips' and action='boat_load')"])assert.ok(progress.includes(clause),clause);
 // Full headers, as live.
 assert.match(header(B,'harvest_event_board'),/\n language sql stable security definer set search_path to '' as $/);
 assert.match(header(B,'harvest_event_pick'),/returns jsonb language plpgsql stable set search_path to '' as $/);
 for(const name of ['harvest_event_league','harvest_event_league_for'])assert.match(header(B,name),/returns smallint language sql immutable set search_path to '' as $/,name);
 for(const name of ['harvest_event_settle','harvest_event_progress','harvest_event_validate'])assert.match(header(B,name),/language plpgsql set search_path to '' as $/,name);
 assert.match(B,/revoke all on function public\.harvest_event_board\(uuid\) from public, anon, authenticated;\ngrant execute on function public\.harvest_event_board\(uuid\) to service_role;/);
 assert.doesNotMatch(B,/create or replace function public\.harvest_event_schedule/);
 // The guard: every live md5, the break, Part A and a lake cast saved by farm-api v231.
 const guard=B.slice(B.indexOf('do $guard$'),B.indexOf('end $guard$'));
 for(const old of Object.values(OLD_MD5))assert.ok(guard.includes(old),old);
 assert.deepEqual(Object.keys(OLD_MD5).sort(),['harvest_event_board(uuid)','harvest_event_league(integer)','harvest_event_pick(bigint)','harvest_event_progress()','harvest_event_settle(uuid)','harvest_event_validate()']);
 assert.match(guard,/if exists\(select 1 from public\.live_events where active and starts_at<=now\(\) and ends_at>now\(\)\) then\n  raise exception 'An event is running/);
 assert.match(guard,/column_name='village_events_finished'\)\n  or not exists\(select 1 from information_schema\.columns where table_schema='public' and table_name='live_event_players' and column_name='world'\)/);
 assert.match(guard,/receipts @> '\[\{"eventAction":"lake_fish"\}\]'/);
 // The refill only adds the village leagues.
 assert.match(B,/jsonb_array_length\(leagues\)=6\) x\n where e\.id=x\.id and \(select jsonb_agg\(v order by i\) from jsonb_array_elements\(x\.l\) with ordinality t\(v,i\) where i<=6\)=e\.leagues;/);
 // The after-check: md5s with is distinct from, the headers and the grants, and last the clock.
 const after=B.slice(B.indexOf('do $after$'));
 assert.match(after,/is distinct from want->>fn then raise exception/);
 for(const field of ['prosecdef','provolatile','proconfig','proacl',"has_function_privilege('service_role','public.harvest_event_league_for(integer,jsonb,smallint)','execute')"])assert.ok(after.includes(field),field);
 assert.match(after,/clock_timestamp\(\) and ends_at>clock_timestamp\(\)\) then\n  raise exception 'Part B ran into the next event; run it again in the next break\.'; end if;\nend \$after\$;/);
 assert.ok(after.includes('<>array[0,0,0,1,4,5,5,6,6,7,7,8,8,9,9,10,10,11,11]::smallint[]'));
 // The md5s in the file are the bodies in the file.
 for(const [name,hash] of Object.entries(NEW_MD5))if(name!=='harvest_event_schedule()')assert.equal(md5(body(B,name.slice(0,name.indexOf('(')))),hash,name);
 assert.equal(NEW_MD5['harvest_event_pick(bigint)'],md5(PICK_BODY));assert.equal(NEW_MD5['harvest_event_validate()'],md5(VALIDATE_BODY));
 assert.ok(after.includes(JSON.stringify(NEW_MD5)));
});

test('every goal in a pool is counted by harvest_event_progress, so none can be unfinishable',()=>{
 const progress=body(B,'harvest_event_progress'),mapped=progress.slice(progress.indexOf('mapped:='),progress.indexOf(';',progress.indexOf('mapped:=')));
 for(const stat of new Set(EVENT_GOAL_POOLS.slice(0,12).flat(2).map(g=>g.stat))){   // the live patch's leagues; the harbour's come with their own
  const prefix=['made_','harvest_','sold_'].find(p=>stat.startsWith(p));
  const ok=(prefix&&mapped.includes(`stat like '${prefix.slice(0,-1)}\\_%'`))||mapped.includes(`stat='${stat}'`)||new RegExp(`stat in \\([^)]*'${stat}'`).test(mapped);
  assert.ok(ok,stat);
 }
 // And the check on events allows them all.
 const validate=body(B,'harvest_event_validate'),allowed=validate.match(/not in \(([^)]*)\)/)[1];
 for(const {stat} of EVENT_GOAL_POOLS.slice(0,12).flat(2))assert.ok(allowed.includes(`'${stat}'`),stat);
});

test('standings: a village league pays its own coins, the diamonds of every league',()=>{
 const now=Date.UTC(2026,9,20,12),iso=t=>new Date(t).toISOString();
 const event={id:'e',starts_at:iso(now-3600e3),ends_at:iso(now+3600e3),objectives:[{stat:'harvested',target:1}],leagues:Array.from({length:12},(_,i)=>({objectives:[{stat:i<6?'harvested':'made_stone',target:1}]})),rewards:{coins:200}};
 const rows=['a','b'].map((id,i)=>({player_id:id,progress:{made_stone:5},actions:3,joined_at:iso(now-3600e3),last_at:iso(now-1800e3+i*60e3)}));
 assert.deepEqual(eventStandings(event,rows,now,EVENT_LEAGUES[6]).map(r=>[r.coins,r.diamonds]),[[22000,25],[12000,15]]);
 assert.deepEqual(eventStandings(event,rows,now,EVENT_LEAGUES[11]).map(r=>[r.coins,r.diamonds]),[[44000,25],[24000,15]]);
 const service=read('supabase/functions/farm-api/event-service.js');
 // The row's stored league first (20 Oct 2026, the owner: the league is set when you join; tests/league-at-join.test.mjs).
 assert.match(service,/own=\[event\.player,mine\]\.find\(r=>Number\.isInteger\(r\?\.league\)\);\n let league=own\?eventLeagueIn\(event,own\.league\):null;/);assert.match(service,/league=eventLeagueFor\(event,me\.data\?\.level\?\?0\)/);
 assert.match(service,/rows\.data\.filter\(r=>eventLeagueIn\(event,r\.league\?\?0\)\.index===league\.index\)/);
 assert.match(service,/title=found\.data\?\.leagues\?\.\[row\.data\?\.league\]\?\.title\?\?found\.data\?\.title\?\?null;/,'the farm journal names the league\'s own title');
});

test('a fish at the village lake counts for village events: farm-api saves it as an event action',()=>{
 assert.ok(!NO_EVENT_ACTIONS.has('lake_fish'));
 for(const action of ['fish','tractor_care','tractor_shift'])assert.ok(NO_EVENT_ACTIONS.has(action),action);
});

test('the event screen: the league card\'s world in the rules, the village line, the league\'s own titles',()=>{
 const ui=read('public/live-events-ui.js');
 assert.match(ui,/const leagueOf=e=>\{const s=e\?\.standings\?\.league,own=eventLeagueOf\(e,e\?\.player,levelOf\(state\)\);return s\?EVENT_LEAGUES\.find\(l=>l\.id===s\.id\)\?\?own:own;\};/);
 assert.match(ui,/EVENT_LEAGUES\.filter\(l=>l\.world===world\)\.map\(/);
 assert.match(ui,/Just play: digging, sawing, packing lunches, helping villagers and fishing on the lake count automatically\./);
 // Since 20 Oct 2026 (the owner) the league is set when you join, so reaching 100 mid-event is one case of the plain rule.
 assert.match(ui,/Your league is set when you join an event \(your first action that counts\), and you finish that event in that league, even if you level up\./);
 assert.doesNotMatch(ui,/during an event and you finish that event in the Valley Legends/);
 assert.match(ui,/From level \$\{WORLD_TWO_LEVEL\} your league is a village league, with goals in the village\. Each village event you finish counts in Village events and in Events finished\./);
 for(const where of ['Final standings · ${esc(ownTitle(e))}','<h3>${esc(ownTitle(e))}</h3>','<strong>${esc(ownTitle(e))}</strong>'])assert.ok(ui.includes(where),where);
});
